from sys import stdin, stdout
import math

MOD = 10**9 + 9

def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def mod_inverse(a, m):
    return pow(a, m - 2, m)

def count_inversions(arr):
    def merge_sort_and_count(arr):
        if len(arr) <= 1:
            return arr, 0
        mid = len(arr) // 2
        left, left_inv = merge_sort_and_count(arr[:mid])
        right, right_inv = merge_sort_and_count(arr[mid:])
        merged, split_inv = merge_and_count(left, right)
        return merged, (left_inv + right_inv + split_inv) % MOD

    def merge_and_count(left, right):
        result = []
        i = j = inv_count = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
                inv_count += (len(left) - i)
        result.extend(left[i:])
        result.extend(right[j:])
        return result, inv_count

    _, inv_count = merge_sort_and_count(arr)
    return inv_count

def solve():
    n = int(stdin.readline().strip())
    arr = list(map(int, stdin.readline().strip().split()))

    inv_count = count_inversions(arr)
    total_permutations = factorial(n)
    unsorted_permutations = (total_permutations - inv_count) % MOD

    stdout.write(str(unsorted_permutations) + '\n')

if __name__ == "__main__":
    solve()

from math import factorial

MOD = 10**9 + 9

def count_unsorted_permutations(n, arr):
    def mod_inv(a, m):
        return pow(a, m - 2, m)

    def derangement(n, m):
        if n == 0:
            return 1
        if n == 1:
            return 0
        return ((n - 1) * (derangement(n - 1, m) + derangement(n - 2, m))) % m

    def count_sorted_elements(arr):
        sorted_count = 0
        max_val = float('-inf')
        min_val = float('inf')
        for num in arr:
            if num >= max_val:
                sorted_count += 1
                max_val = num
            if num <= min_val:
                sorted_count += 1
                min_val = num
        return sorted_count

    sorted_count = count_sorted_elements(arr)
    unsorted_count = n - sorted_count
    if unsorted_count == 0:
        return 0

    derange_result = derangement(unsorted_count, MOD)
    perm_result = factorial(unsorted_count) % MOD
    result = (perm_result * mod_inv(derange_result, MOD)) % MOD
    return result

