from typing import List

def count_unsorted_permutations(n: int, a: List[int]) -> int:
    MOD = 10**9 + 9

    # Initialize variables to store the counts of strictly increasing and decreasing segments
    inc_count = [0] * n
    dec_count = [0] * n

    # Count strictly increasing segments
    for i in range(1, n):
        if a[i] > a[i - 1]:
            inc_count[i] = inc_count[i - 1] + 1

    # Count strictly decreasing segments
    for i in range(n - 2, -1, -1):
        if a[i] > a[i + 1]:
            dec_count[i] = dec_count[i + 1] + 1

    # Calculate the total number of unsorted permutations
    unsorted_permutations = 0
    for i in range(n):
        if i == 0:
            unsorted_permutations += 1
        elif i == n - 1:
            unsorted_permutations += 1
        else:
            unsorted_permutations += (inc_count[i - 1] + 1) * (dec_count[i + 1] + 1)

    return unsorted_permutations % MOD

